//! Module: lightning.tools.contract
//! Purpose: Generate shared C memory/scanout constants and the scanout/cursor policy declarations.
//! Created: 2026-10-08
//! Architecture: Called before compilation; QEMU and the Windows KMD use identical constants.
use std::{fs, io, path::Path};
#[path = "../../lightning/core/src/memory_contract.rs"]
pub mod memory_contract;
#[path = "../../lightning/core/src/scanout_contract.rs"]
pub mod scanout_contract;

pub fn generate(source: &Path) -> io::Result<()> {
    let mut text = String::from(
        "/* Generated by tools/lightning/contract.rs; do not edit. */\n#ifndef HW_MISC_LIGHTNING_MEMORY_H\n#define HW_MISC_LIGHTNING_MEMORY_H\n",
    );
    memory_contract::visit(|name, value| {
        text.push_str(&format!("#define LIGHTNING_MEMORY_{name} {value}u\n"));
    });
    scanout_contract::visit(|name, value| {
        text.push_str(&format!("#define LIGHTNING_SCANOUT_{name} {value}u\n"));
    });
    text.push_str("#include <stdbool.h>\n#include <stddef.h>\n#include <stdint.h>\nbool lightning_scanout_valid(uint32_t width, uint32_t height, uint32_t stride, uint32_t offset, uint64_t capacity);\n");
    text.push_str("bool lightning_cursor_convert(uint32_t format, uint32_t width, uint32_t height, uint32_t pitch, uint32_t hot_x, uint32_t hot_y, const uint8_t *shape, size_t shape_bytes, uint32_t *pixels, size_t pixel_count);\n");
    text.push_str("#endif\n");
    let path = source.join("include/hw/misc/lightning-memory.h");

    if fs::read_to_string(&path).ok().as_deref() != Some(&text) {
        fs::write(path, text)?;
    }
    Ok(())
}
